        >>> weather_list = {'New York': {'weather': 'sunny','temperature': 27,'temperature units': 'celsius'},'Beijing': {'weather': 'cloudy','temperature': 23,'temperature units': 'celsius'}}
        >>> weatherSystem.query(weather_list)
        (27, 'sunny')

        """
    if self.city in weather_list:
        weather_info = weather_list[self.city]
        self.temperature = float(weather_info['temperature'])
        self.weather = weather_info['weather']
        if tmp_units == 'celsius':
            return (self.temperature, self.weather)
        elif tmp_units == 'fahrenheit':
            return (self.celsius_to_fahrenheit(), self.weather)
        else:
            raise ValueError("Unsupported temperature unit. Use 'celsius' or 'fahrenheit'.")
    else:
        raise KeyError('City not found in the weather list.')

